dir:


















































































































			declare @chon_yn int, @q varchar(4000)
			set @chon_yn = 1

			select @chon_yn chon_yn,a.id,a.so_ct,a.ma_ct,a.ngay_ct,a.ma_nt,a.ty_gia,a.ma_kh,b.ten_kh,a.t_tt,t_tt*0 as da_tt_nt,t_tt*0 as cl_nt into #v
			from ctqlq20 a 
			left join dmkh b  on a.ma_kh = b.ma_kh
			where a.ma_kh = @ma_kh and a.unit_id = @unit_id and ngay_ct between @ngay_ct1 and @ngay_ct2 and a.loai_tt = 0 and (tt_yn = 0 or (id in (select id_tt from ctqlq20 where id = 0 and loai_tt = 1)))

			set @q = '
			  update #v set da_tt_nt = b.tt from #v a join (select id_tt, sum(tt) as tt from ctqlq20 x1 where x1.loai_tt = 1 and id <> ' + rtrim(@id) + ' and exists (select 1 from #v x2 where x1.id_tt = x2.id) group by id_tt) b on a.id = b.id_tt
			  update #v set cl_nt = t_tt - da_tt_nt'
			exec (@q)

			select a.*, a.id as id_hd, a.so_ct as so_ct_hd, a.ma_ct as ma_ct_hd,a.ngay_ct as ngay_ct_hd, a.ma_nt as ma_nt_hd, a.ty_gia as ty_gia_hd, a.t_tt as tien_hd_nt,  da_tt_nt as da_pb_nt,b.id_dh into #d from #v a 
				left join m82 b on a.id = b.id and a.ma_ct  ='PU1'

				select a.*,b.ma_job as ma_job_dh, b.ma_ct as ma_ct_dh, b.so_job as so_job_dh, b.ngay_ct as ngay_ct_dh, b.so_ct as so_ct_dh from #d a left join s61 b on a.id_dh = b.id 
			drop table #v,#d









  &DefaultButton;




function filter$q64_1Select(p){
  this.constructor(p);
}
filter$q64_1Select.prototype = new DirEvent();
filter$q64_1Select.prototype.beforeInit = function(){
  var p = this._dir;

}


filter$q64_1Select.prototype.afterInit = function(){
  var p = this._dir,g = p.grid(0),master = g.ds.get(1), rErr = '';
	p.valForm(['ngay_ct1','ngay_ct2','id', 'ma_kh', 'ten_kh', 'unit_id'], [p.options._ngay_ct1,p.options._ngay_ct2,p.options._so_ct,p.options._ma_kh, p.options._ten_kh, p.options._unit_id]);
	//var ima_kh = master.val(0, 'ma_kh');
	//var iten_kh = master.val(0, 'ten_kh');

	  //p.valForm(['ma_kh','ten_kh'],[ima_kh,iten_kh]);

	//dir$s611BQ1SetMaster(p);

}

function dir$s611BQ1SetMaster(p) {
  p.request('ma_kh_request', '', ['id']);
}

filter$q64_1Select.prototype.beforeAcceptFilter = function (m2, opt, sub) {
  var p = this._dir, pa = p.options.parent, g = p.grid(0), dt = g.data, master = g.ds.get(1), rErr = dt.findRow("[so_luong0] > [sl_cl]");

  var fun = function(){
    dt.removeRow('[chon_yn] == 0'); 
    pa.appendGrid(0, dt, p.valForm('xprocess') == "2", 'chon_yn', 'chon_yn');
    //pa.calcExpressionAll(0, 'chon_yn');
	//p.request('ma_kh_request', '', ['id']);
    //pa.appendForm(master, 0);
	p._close();
  }

  if (rErr.length) {
    $.question('$VoucherRetrieveLimit', null, p, function(q, v){
      q._close();
      if (v) fun();
    });
  } else fun();

    return false;
}
